$ErrorActionPreference='Stop'
Add-Type -AssemblyName System.IO.Compression.FileSystem
$zip=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_energy_public-dataset_v2.zip'
$out=Join-Path $env:USERPROFILE 'Downloads\TGCV_MT4_5_LF_INCONSISTENCY_SEMANTIC_SUMMARY_001.txt'
$expected='691F950A314015A7DE9D4CBABCC177846D74ABF7036B6A89E192B152A88E6D30';$sha=(Get-FileHash $zip -Algorithm SHA256).Hash.ToUpperInvariant();$md5=(Get-FileHash $zip -Algorithm MD5).Hash.ToUpperInvariant();if($sha-ne$expected){throw 'ZIP SHA256 mismatch'}
function Parse([string]$l){$l -split ',(?=(?:[^\"]*\"[^\"]*\")*[^\"]*$)',10};function Clean([string]$s){if($null-eq$s){return ''};$s.Trim().Trim('"')}
$rows=@();$z=[IO.Compression.ZipFile]::OpenRead($zip);try{foreach($e in $z.Entries|Where-Object{$_.FullName-match'/Technologies/[^/]+\.csv$'}){$r=[IO.StreamReader]::new($e.Open());try{while(($l=$r.ReadLine())-ne$null){$x=Parse $l;if($x.Count-lt 10){continue};$p=Clean $x[2];if($p-ne'LF_min' -and $p-ne'LF_max'){continue};$v=Clean $x[5];if([string]::IsNullOrWhiteSpace($v)){continue};$rows+=,[pscustomobject]@{Path=$e.FullName;Country=Clean $x[0];Technology=[IO.Path]::GetFileNameWithoutExtension($e.Name);Year=Clean $x[3];Parameter=$p;Value=$v;Reference=Clean $x[7];Note=Clean $x[9]}}finally{$r.Dispose()}}}finally{$z.Dispose()}
$groups=$rows|Group-Object Country,Technology,Year; $bad=@();foreach($g in $groups){$a=$g.Group|Where-Object Parameter-eq'LF_min'|Select-Object -First 1;$b=$g.Group|Where-Object Parameter-eq'LF_max'|Select-Object -First 1;if($a -and $b){$av=0.0;$bv=0.0;if([double]::TryParse($a.Value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$av)-and[double]::TryParse($b.Value,[Globalization.NumberStyles]::Float,[Globalization.CultureInfo]::InvariantCulture,[ref]$bv)-and $av-gt$bv){$bad+=[pscustomobject]@{Country=$a.Country;Technology=$a.Technology;Year=$a.Year;LF_min=$a.Value;LF_max=$b.Value;LFminRef=$a.Reference;LFmaxRef=$b.Reference;LFminNote=$a.Note;LFmaxNote=$b.Note}}}}
$lines=@('TGCV MT4-5 - LF INCONSISTENCY SEMANTIC AUDITOR 001',"SHA256=$sha","MD5=$md5","TOTAL_LF_INCONSISTENCY_CELLS=$($bad.Count)",'','PURPOSE=Inspect any genuine LF_min > LF_max cases after invariant-culture parsing. This is a semantic/provenance diagnostic only.','RULE=Do not repair, impute, swap, or reinterpret values.','');if($bad.Count){$lines+=($bad|ForEach-Object{"$($_.Country)|$($_.Technology)|$($_.Year)|LF_min=$($_.LF_min)|LF_max=$($_.LF_max)|LFminRef=$($_.LFminRef)|LFmaxRef=$($_.LFmaxRef)|LFminNote=$($_.LFminNote)|LFmaxNote=$($_.LFmaxNote)"})}else{$lines+='RESULT=No invariant-culture LF_min > LF_max cells found.'};$lines+=@('','INTERPRETATION=If zero, prior 802 default-culture discrepancies are parser artifacts and provide no evidence against CORE_6.','SUFFICIENT_FOR_P_tau=UNDETERMINED','STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION');[IO.File]::WriteAllLines($out,$lines);Write-Output "OUTPUT=$out";Write-Output "SHA256=$sha";Write-Output "MD5=$md5";Write-Output "TOTAL_LF_INCONSISTENCY_CELLS=$($bad.Count)";Write-Output 'SUFFICIENT_FOR_P_tau=UNDETERMINED';Write-Output 'STATUS=ANALYTICAL DIAGNOSTIC - NOT A FINAL MT4-5 GATE DECISION'